// spec: specs/events.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

const EVENT_PATH = '/events/087e8dd0-3043-4e55-b182-c2b646c7b7f8';
const EVENT_URL_RE = /\/events\/087e8dd0-3043-4e55-b182-c2b646c7b7f8$/;

test.describe('רכישת כרטיס לאירוע', () => {
  test('יתרה לא מספיקה: "אין מספיק יתרה זמינה בארנק." והרכישה לא מתבצעת @android @prod-safe #6a86f7bc4808', async ({ page }) => {
    // 1. /wallet — היתרה הזמינה; אם ≥ ₪11,100 מדלגים ולא לוחצים
    await page.goto('/wallet');
    const balanceBefore = await page.getByTestId('balance-available').innerText();
    test.skip(
      Number(balanceBefore.replace(/[^\d.]/g, '')) >= 11100,
      'баланс client ≥ ₪11,100 — клик купит билет',
    );

    // 2. לפתוח את האירוע; רדיו "QA VIP"; "הוספת כרטיס" × 5; סה"כ ₪11,100
    await page.goto(EVENT_PATH);
    await page.getByRole('radio', { name: 'QA VIP, ₪1,850' }).click();
    for (let i = 0; i < 5; i++) await page.getByRole('button', { name: 'הוספת כרטיס' }).click();
    await expect(page.getByTestId('summary-total')).toHaveText('₪11,100');

    // 3. אימייל תקין
    await page.getByRole('textbox', { name: 'אימייל לקבלת הכרטיס' }).fill('qa-auto@example.com');

    // 4. "קניית כרטיס" (הסה"כ גבוה מהיתרה — אי אפשר לחייב)
    await page.getByRole('button', { name: 'קניית כרטיס' }).click();
    await expect(page.getByText('אין מספיק יתרה זמינה בארנק.')).toBeVisible();
    await expect(page).toHaveURL(EVENT_URL_RE);
    await expect(page.getByText('הרכישה בוצעה בהצלחה!')).toHaveCount(0);
    await expect(page.getByText('כתובת האימייל אינה תקינה')).toHaveCount(0);

    // היתרה לא השתנתה
    await page.goto('/wallet');
    await expect(page.getByTestId('balance-available')).toHaveText(balanceBefore);
  });
});
